import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Dépôt de démonstration","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/atlas-plugins/demo-repository.md","filePath":"fr/projects/atlas-plugins/demo-repository.md","lastUpdated":1792849697000}'),o={name:"fr/projects/atlas-plugins/demo-repository.md"};function r(l,e,n,d,p,u){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="depot-de-demonstration" tabindex="-1">Dépôt de démonstration <a class="header-anchor" href="#depot-de-demonstration" aria-label="Permalink to &quot;Dépôt de démonstration&quot;">​</a></h1><p>Le dépôt de démonstration est la source réelle de test du processus d’installation ATLAS :</p><p><code>https://github.com/rockbaer2007/atlas-plugin-repository-demo</code></p><p>Pour créer votre propre dépôt de plugins, utilisez le <a href="https://github.com/rockbaer2007/atlas-plugin-template" target="_blank" rel="noreferrer">modèle de plugin ATLAS</a>.</p><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li>Ajouter un dépôt de plugins dans l’Administration.</li><li>Valider les marqueurs du dépôt.</li><li>Afficher les plugins disponibles dans le Hub et l’Administration.</li><li>Comparer les versions et signaler les mises à jour.</li><li>Tester la page de transition vers l’installation.</li><li>Charger ATLAS File Studio comme deuxième entrée de plugin réelle.</li><li>Vérifier l’installation et les mises à jour de l’application Home Assistant à partir de dépôts GitHub réels.</li></ul><h2 id="page-d-installation" tabindex="-1">Page d’installation <a class="header-anchor" href="#page-d-installation" aria-label="Permalink to &quot;Page d’installation&quot;">​</a></h2><p>La page publique est hébergée sur GitHub Pages :</p><p><code>https://rockbaer2007.github.io/atlas-plugin-repository-demo/install.html</code></p><p>Le bouton copie l’URL du dépôt ATLAS et explique comment la coller dans l’Administration. Il n’ouvre pas le magasin d’extensions Home Assistant : les plugins ATLAS et les extensions Home Assistant utilisent des formats de dépôt différents.</p><h2 id="test-de-mise-a-jour" tabindex="-1">Test de mise à jour <a class="header-anchor" href="#test-de-mise-a-jour" aria-label="Permalink to &quot;Test de mise à jour&quot;">​</a></h2><p>Toute modification fonctionnelle d’un package doit augmenter sa version. L’Administration peut alors détecter la mise à jour par rapport à la version installée.</p><p>Cette règle concerne aussi les packages de test : les changements d’interface, de manifeste, d’icônes, de contenu ou de comportement doivent être accompagnés d’une nouvelle version publiée.</p>',13)])])}const g=t(o,[["render",r]]);export{m as __pageData,g as default};
